// Sky presets: per kind of weather, the
// sky gradient table, the four cloud decks (back to front: cloud family, count,
// scale range, height, drift velocity range, emitter extent x/y/z, then how solid and how
// tall its clouds are drawn, if not as baked; `wideDecks` for landscape windows), the blanket, enabled layers, rain,
// snow, hail and sleet particle settings, stars, and lighting keyframes by solar
// elevation.
// Light keyframe: [elevation, isPM, sun color, sun intensity, ambient color,
// ambient intensity, fill color, fill intensity, cloud colors (bbg, bg, fg, ffg,
// blanket), cloud brightness (same order), star opacity, the sun's angle on the clouds
// ([pitch, yaw] in degrees: see sunDirection)].
// Sun rays: [angle°, color, count, length range, spread°]; ghosts (lens ghosts):
// [opacity, count, length, size range]; rainbow: [scale, opacity]; lightning:
// strike settings (interval in seconds; grow, flash and fade in seconds).
// Gradient stop: [elevation, isPM, top, middle, bottom, middle stop point].

// Kinds of sky, the gradient tables they use, their layers and their cloud families.
export type SkyKind = 'clear' | 'mostlyClear' | 'partlyCloudyMidAltitude' | 'mostlyCloudyMidAltitude' | 'cloudyMidAltitude' | 'cloudyLowAltitude' | 'cloudyHighAltitude'
  | 'mostlyCloudyLowAltitude' | 'partlyCloudyLowAltitude' | 'mostlyCloudyHighAltitude' | 'partlyCloudyHighAltitude' | 'foggy' | 'haze' | 'drizzle' | 'rain' | 'heavyRain' | 'thunderstorms' | 'isolatedThunderstorms'
  | 'scatteredThunderstorms' | 'strongStorms' | 'sunShowers' | 'freezingDrizzle' | 'snow' | 'flurries' | 'heavySnow' | 'sleet' | 'wintryMix' | 'hail' | 'blowingSnow'
  | 'smoky' | 'hurricane' | 'freezingRain' | 'blizzard' | 'tropicalStorm' | 'blowingDust';
export type GradientName = 'default_low' | 'default_mid' | 'default_high' | 'overcast_mid' | 'overcast_low' | 'overcast_high' | 'haze' | 'rain' | 'rainheavy' | 'snow' | 'snowheavy' | 'smoky' | 'hurricane';
export type SkyLayer = 'stars' | 'shootingStar' | 'sunBeams' | 'sunDisc' | 'sunHalo' | 'sunGhosts' | 'moon' | 'fringe' | 'rain' | 'nearParticles' | 'fog' | 'lightning'
  | 'cloudFlash' | 'snow' | 'sleet' | 'hail' | 'dust';
export type CloudFamily = 'cirrostratus' | 'cirrus' | 'altostratus' | 'wispy' | 'cumulus' | 'nimbus' | 'stratus';
export type Range = readonly [low: number, high: number];
export type Deck = readonly [family: CloudFamily, count: number, scale: Range, height: number, velocity: Range, emitter: readonly [x: number, y: number, z: number], thin?: number, tall?: number];
export type Decks = readonly [Deck | null, Deck | null, Deck | null, Deck | null];
type Particles = readonly [count: number, speed: number, size: Range];
export interface Lightning {
  strikeInterval: Range;
  branchCount: number;
  roughness: number;
  totalStrikeLength: number;
  growAmount: number;
  flashAmount: number;
  fadeAmount: number;
  glow: number;
  screenFlashProbability: number;
  screenFlashBrightness: Range;
  screenFlashFadeLength: number;
  cloudFlashProbability: number;
  // The bolt's width in scene units, and how many times wider it flashes.
  thickness: number;
  flashThickness: number;
  // How far either side of the bolt's foot its branches head, in scene units.
  branchSpread: number;
  // Branches thin away from when the bolt has grown until growAmount + branchFadeAmount
  // of the way through the strike (a share of it, though both are given in seconds).
  branchFadeAmount: number;
  // How bright the light flickering behind the clouds gets (see cloudFlash).
  cloudFlashBrightness: number;
}
// Falling rain as drawn on a wide window, in scene units and seconds. Drops fall for `life`
// from a line `offset` above the frame's centre, `angle` degrees off straight down (turned
// with the line), swaying `sway` [degrees, radians per second] either way. Each layer (the
// near one in front, the far one behind) spawns `rate` drops a second, falling at up to
// `speed`, `size` wide (and about four times as long), each at an opacity drawn between
// `alpha`'s two, within `spread` degrees of the fall.
export type RainLayer = readonly [rate: number, speed: number, size: Range, alpha: Range, spread: number];
export interface RainFall {
  life: number;
  angle: number;
  offset: number;
  sway: Range;
  front: RainLayer;
  back: RainLayer;
}
type Five<T> = readonly [T, T, T, T, T];
export type LightKeyframe = readonly [elevation: number, pm: 0 | 1, sun: string, sunIntensity: number, ambient: string, ambientIntensity: number, fill: string,
  fillIntensity: number, clouds: Five<string>, brightness: Five<number>, stars: number, sunAngle: readonly [pitch: number, yaw: number]];
export type GradientStop = readonly [elevation: number, pm: 0 | 1, top: string, middle: string, bottom: string, stop: number];
export interface SkyLook {
  // Its clouds are mist or smoke, which keep their own colour from every side instead of being lit.
  selfLit?: true;
  sky: GradientName;
  decks: Decks;
  wideDecks: Decks;
  blanket: readonly [family: CloudFamily, size: number, rise: number] | null;
  // A sky with no lid may have a veil instead: cirrus streaks stretched across it, high up, at an
  // opacity of their own, which leave the sky under them clear.
  veil?: readonly [size: number, rise: number, opacity: number];
  // Where the sky by day has clouds of its own, those it takes while the sun is up.
  day?: { decks: Decks; wideDecks: Decks };
  layers: readonly SkyLayer[];
  collision: 'none' | 'rain' | 'snow' | 'hail';
  rain: readonly [front: Particles, back: Particles];
  snow: readonly [front: Particles, back: Particles];
  hail: Particles;
  sleet: readonly [front: readonly [count: number, speed: number], back: readonly [count: number, speed: number]];
  stars: readonly [number, number, number, number];
  rays: readonly [angle: number, color: string, count: number, length: Range, spread: number];
  ghosts: readonly [opacity: number, count: number, length: number, size: Range];
  rainbow: readonly [scale: number, opacity: number];
  lightning: Lightning;
  rainFall: RainFall;
  // Rain splashing on the panels' top edges: the odds that a near drop reaching an edge
  // splashes, and its droplets' size (scene units), life (seconds) and launch speed (units a
  // second).
  splash: { odds: number; size: Range; life: Range; speed: Range };
  fallAngle: number;
  collision_probability: number;
  light: readonly LightKeyframe[];
  // The light while the moon shows in the sky, where the kind has one: bluer by night, and through
  // twilight its own.
  moonLight?: readonly LightKeyframe[];
}
export interface PresetData {
  kinds: Readonly<Record<SkyKind, SkyLook>>;
  gradients: Readonly<Record<GradientName, readonly GradientStop[]>>;
}
export type SunKeyframe = readonly [hour: number, position: readonly [x: number, y: number], rayAngle: number, rainbow: number, ghosts: number];
